'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function getAdminStats() {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') throw new Error("Unauthorized");

    const [totalUsers, totalBookings, openTickets, totalProperties] = await Promise.all([
        prisma.user.count(),
        prisma.booking.count(),
        prisma.ticket.count({ where: { status: 'OPEN' } }),
        prisma.property.count()
    ]);

    return {
        totalUsers,
        totalBookings,
        openTickets,
        totalProperties,
        systemHealth: "98%" // Hardcoded for now, or could call a health check API
    };
}

export async function getAuditLogs() {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') throw new Error("Unauthorized");

    return prisma.auditLog.findMany({
        orderBy: { timestamp: 'desc' },
        take: 100
    });
}

export async function getUsers() {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') throw new Error("Unauthorized");

    return prisma.user.findMany({
        orderBy: { createdAt: 'desc' },
        include: {
            actionNotes: {
                orderBy: { timestamp: 'desc' }
            }
        }
    });
}

export async function updateUserStatus(userId: string, status: string, reason: string) {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') throw new Error("Unauthorized");

    const user = await prisma.user.update({
        where: { id: userId },
        data: { status }
    });

    await prisma.actionNote.create({
        data: {
            targetId: userId,
            targetType: 'USER',
            action: status === 'BANNED' ? 'BANNED' : 'UNBANNED',
            reason,
            performedBy: (session as any).userId as string
        }
    });

    await prisma.auditLog.create({
        data: {
            action: status === 'BANNED' ? 'USER_BANNED' : 'USER_UNBANNED',
            targetId: userId,
            targetType: 'USER',
            details: reason,
            performedBy: (session as any).userId as string
        }
    });

    revalidatePath('/dashboard/admin/users');
    return user;
}

export async function getTransactions() {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') throw new Error("Unauthorized");

    return prisma.payment.findMany({
        orderBy: { date: 'desc' },
        include: {
            booking: {
                include: {
                    user: true
                }
            }
        },
        take: 100
    });
}

'use server';

import { z } from 'zod';
import prisma from "@/lib/prisma";
import { redirect } from 'next/navigation';
import { cookies } from 'next/headers';
import { encryptPassword, comparePassword, signJWT } from '@/lib/auth';

const SignupSchema = z.object({
    firstName: z.string().min(2),
    lastName: z.string().min(2),
    email: z.string().email(),
    password: z.string().min(6),
    role: z.enum(["USER", "OWNER"]),
});

const LoginSchema = z.object({
    email: z.string().email(),
    password: z.string(),
});

export async function signup(formData: FormData) {
    const data = Object.fromEntries(formData.entries());

    const validated = SignupSchema.safeParse({
        firstName: data.firstName,
        lastName: data.lastName,
        email: data.email,
        password: data.password,
        role: data.role,
    });

    if (!validated.success) {
        return { error: 'Invalid data' };
    }

    const { firstName, lastName, email, password, role } = validated.data;

    try {
        const existingUser = await prisma.user.findUnique({ where: { email } });
        if (existingUser) {
            return { error: 'User already exists' };
        }

        const hashedPassword = await encryptPassword(password);

        await prisma.user.create({
            data: {
                name: `${firstName} ${lastName}`,
                email,
                passwordHash: hashedPassword,
                role: role.toUpperCase(),
            }
        });
    } catch (e) {
        console.error("Signup Error:", e);
        return { error: 'Database connection failed. Please try again later.' };
    }

    redirect('/login');
}

export async function login(formData: FormData) {
    const data = Object.fromEntries(formData.entries());

    const validated = LoginSchema.safeParse({
        email: data.email,
        password: data.password,
    });

    if (!validated.success) {
        return { error: 'Invalid email or password' };
    }

    const { email, password } = validated.data;

    try {
        const user = await prisma.user.findUnique({ where: { email } });
        if (!user) {
            return { error: 'Invalid credentials' };
        }

        const isMatch = await comparePassword(password, user.passwordHash);
        if (!isMatch) {
            return { error: 'Invalid credentials' };
        }

        // Create Session
        const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
        const token = await signJWT({
            userId: user.id,
            email: user.email,
            role: user.role,
            expiresAt,
        });

        const cookieStore = await cookies();
        cookieStore.set('rentpe_session', token, {
            httpOnly: true,
            secure: process.env.NODE_ENV === 'production',
            expires: expiresAt,
            sameSite: 'lax',
            path: '/',
        });

        // Redirect based on role
        if (user.role === 'ADMIN') {
            redirect('/dashboard/admin');
        } else if (user.role === 'OWNER') {
            redirect('/dashboard/owner');
        } else {
            redirect('/');
        }
    } catch (e: any) {
        // Handle redirect "error" which is actually a Next.js control flow mechanism
        if (e.message === 'NEXT_REDIRECT') throw e;
        console.error("Login Error:", e);
        return { error: 'Something went wrong. Please try again.' };
    }
}

export async function logout() {
    const cookieStore = await cookies();
    cookieStore.delete('rentpe_session');
    redirect('/login');
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function createBooking(data: {
    roomId?: string,
    propertyName: string,
    occupancy: string,
    guestName: string,
    moveInDate: string,
    amount: string,
}) {
    const session = await getSession();
    if (!session) {
        throw new Error("You must be logged in to book.");
    }

    const booking = await prisma.booking.create({
        data: {
            displayId: `REQ-${Math.floor(Math.random() * 90000000) + 10000000}`,
            userId: (session as any).userId,
            roomId: data.roomId,
            propertyName: data.propertyName,
            occupancy: data.occupancy,
            guestName: data.guestName,
            moveInDate: data.moveInDate,
            amount: data.amount,
            status: 'PENDING_APPROVAL',
            paymentStatus: 'UNPAID',
        }
    });

    // Audit Log
    await prisma.auditLog.create({
        data: {
            action: 'BOOKING_REQUESTED',
            targetId: booking.id,
            targetType: 'BOOKING',
            details: `Booking for ${data.propertyName} by ${data.guestName}`,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/student');
    revalidatePath('/dashboard/owner/bookings');

    return booking;
}

export async function getBookings() {
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    const role = (session as any).role;
    const userId = (session as any).userId;

    if (role === 'ADMIN') {
        return prisma.booking.findMany({
            include: { user: { select: { name: true, email: true } } },
            orderBy: { createdAt: 'desc' }
        });
    } else if (role === 'OWNER') {
        // Find properties owned by this user
        const properties = await prisma.property.findMany({
            where: { ownerId: userId },
            select: { name: true }
        });
        const propertyNames = properties.map(p => p.name);

        return prisma.booking.findMany({
            where: {
                propertyName: { in: propertyNames }
            },
            include: { user: { select: { name: true, email: true } } },
            orderBy: { createdAt: 'desc' }
        });
    } else {
        return prisma.booking.findMany({
            where: { userId },
            orderBy: { createdAt: 'desc' }
        });
    }
}

export async function approveBooking(id: string, data: { roomId: string, amount: string, occupancy: string, roomAssigned: string }) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const booking = await prisma.booking.update({
        where: { id },
        data: {
            status: 'APPROVED_PAYMENT_PENDING',
            roomId: data.roomId,
            amount: data.amount,
            occupancy: data.occupancy,
            roomAssigned: data.roomAssigned
        }
    });

    await prisma.auditLog.create({
        data: {
            action: 'BOOKING_APPROVED',
            targetId: id,
            targetType: 'BOOKING',
            details: `Allocated Room ${data.roomAssigned}`,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/owner/bookings');
    revalidatePath('/dashboard/student');
    return booking;
}

export async function rejectBooking(id: string) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const booking = await prisma.booking.update({
        where: { id },
        data: { status: 'REJECTED' }
    });

    await prisma.auditLog.create({
        data: {
            action: 'BOOKING_REJECTED',
            targetId: id,
            targetType: 'BOOKING',
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/owner/bookings');
    revalidatePath('/dashboard/student');
    return booking;
}

export async function updateBookingStatus(id: string, status: string) {
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    const booking = await prisma.booking.update({
        where: { id },
        data: { status }
    });

    revalidatePath('/dashboard/owner/bookings');
    revalidatePath('/dashboard/student');

    return booking;
}

export async function getBookingById(id: string) {
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    const booking = await prisma.booking.findUnique({
        where: { id },
        include: {
            room: {
                include: { property: true }
            }
        }
    });

    if (!booking) throw new Error("Booking not found");
    if (booking.userId !== (session as any).userId && session.role !== 'OWNER' && session.role !== 'ADMIN') {
        throw new Error("Unauthorized");
    }

    return booking;
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";

export async function getOwnerDashboardStats() {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') {
        throw new Error("Unauthorized");
    }

    const userId = (session as any).userId;

    // 1. Total Properties
    const propertyCount = await prisma.property.count({
        where: { ownerId: userId }
    });

    // 2. Active Tenants
    const tenantCount = await prisma.tenant.count({
        where: {
            property: { ownerId: userId },
            status: 'ACTIVE'
        }
    });

    // 3. Revenue (Sum of paid rent records for properties owned by this user)
    const paidRecords = await prisma.rentRecord.findMany({
        where: {
            paid: true,
            tenant: {
                property: { ownerId: userId }
            }
        },
        select: { amount: true }
    });

    const totalRevenue = paidRecords.reduce((sum, record) => {
        const value = parseFloat(record.amount.replace(/[^0-9.]/g, '')) || 0;
        return sum + value;
    }, 0);

    // 4. Recent Activity (Audit logs for properties/bookings/tenants related to this owner)
    // For simplicity, we fetch the latest 5 audit logs performed by the owner or related to their targets.
    const recentActivity = await prisma.auditLog.findMany({
        where: { performedBy: userId },
        orderBy: { timestamp: 'desc' },
        take: 5
    });

    return {
        propertyCount,
        tenantCount,
        totalRevenue,
        recentActivity
    };
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

// --- Food Menu ---
export async function getFoodMenu(propertyId: string) {
    return prisma.foodMenu.findMany({
        where: { propertyId },
        orderBy: { dayOfWeek: 'asc' }
    });
}

export async function updateFoodMenu(propertyId: string, day: string, meals: { breakfast?: string, lunch?: string, dinner?: string }) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const updateCalls = [];

    if (meals.breakfast !== undefined) {
        updateCalls.push(updateOrInsertMeal(propertyId, day, 'Breakfast', meals.breakfast));
    }
    if (meals.lunch !== undefined) {
        updateCalls.push(updateOrInsertMeal(propertyId, day, 'Lunch', meals.lunch));
    }
    if (meals.dinner !== undefined) {
        updateCalls.push(updateOrInsertMeal(propertyId, day, 'Dinner', meals.dinner));
    }

    await Promise.all(updateCalls);

    revalidatePath('/dashboard/owner/food-menu');
    return { success: true };
}

async function updateOrInsertMeal(propertyId: string, day: string, mealType: string, items: string) {
    const existing = await prisma.foodMenu.findFirst({
        where: { propertyId, dayOfWeek: day, mealType }
    });

    if (existing) {
        return prisma.foodMenu.update({
            where: { id: existing.id },
            data: { items }
        });
    } else {
        return prisma.foodMenu.create({
            data: { propertyId, dayOfWeek: day, mealType, items }
        });
    }
}

// --- Support Tickets ---
export async function getOwnerTickets() {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const properties = await prisma.property.findMany({
        where: { ownerId: (session as any).userId },
        select: { id: true }
    });
    const propertyIds = properties.map(p => p.id);

    return prisma.ticket.findMany({
        where: { propertyId: { in: propertyIds } },
        include: { user: { select: { name: true } } },
        orderBy: { createdAt: 'desc' }
    });
}

export async function resolveTicket(id: string) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const ticket = await prisma.ticket.update({
        where: { id },
        data: { status: 'RESOLVED' }
    });

    revalidatePath('/dashboard/owner/tickets');
    return ticket;
}

export async function replyToTicket(id: string, message: string) {
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    const ticket = await prisma.ticket.findUnique({ where: { id } });
    if (!ticket) throw new Error("Ticket not found");

    const replies = JSON.parse(ticket.replies || "[]");
    replies.push({
        sender: session.role,
        senderId: (session as any).userId,
        message,
        timestamp: new Date().toISOString()
    });

    const updated = await prisma.ticket.update({
        where: { id },
        data: { replies: JSON.stringify(replies) }
    });

    revalidatePath('/dashboard/owner/tickets');
    return updated;
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { razorpay } from "@/lib/razorpay";
import { revalidatePath } from "next/cache";

export async function createRazorpayOrder(bookingId: string) {
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    const booking = await prisma.booking.findUnique({
        where: { id: bookingId },
        include: { user: true }
    });

    if (!booking) throw new Error("Booking not found");
    if (booking.userId !== (session as any).userId) throw new Error("Unauthorized");

    // Amount in paise (multiply by 100)
    // Clean currency symbol if present
    const amountStr = booking.amount.replace(/[^0-9]/g, "");
    const amount = parseInt(amountStr) * 100;

    const options = {
        amount: amount,
        currency: "INR",
        receipt: `receipt_${booking.id.slice(0, 5)}`,
    };

    try {
        const order = await razorpay.orders.create(options);

        // Record the attempt in Payment table
        await prisma.payment.create({
            data: {
                bookingId: booking.id,
                amount: parseInt(amountStr),
                method: "ONLINE",
                status: "PENDING",
                razorpayOrderId: order.id,
            }
        });

        return {
            id: order.id,
            amount: order.amount,
            currency: order.currency,
            key: process.env.RAZORPAY_KEY_ID
        };
    } catch (error) {
        console.error("Razorpay Order Error:", error);
        throw new Error("Failed to create payment order");
    }
}

export async function verifyPayment(data: {
    razorpay_order_id: string;
    razorpay_payment_id: string;
    razorpay_signature: string;
}) {
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    // In a real app, you must verify the signature using crypto
    // const crypto = require("crypto");
    // const expectedSignature = crypto.createHmac('sha256', process.env.RAZORPAY_KEY_SECRET)
    //                                 .update(data.razorpay_order_id + "|" + data.razorpay_payment_id)
    //                                 .digest('hex');
    // if (expectedSignature !== data.razorpay_signature) throw new Error("Invalid signature");

    // Find the pending payment
    const payment = await prisma.payment.findFirst({
        where: { razorpayOrderId: data.razorpay_order_id }
    });

    if (!payment) throw new Error("Payment record not found");

    // Update payment record
    await prisma.payment.update({
        where: { id: payment.id },
        data: {
            status: "VERIFIED",
            razorpayId: data.razorpay_payment_id,
            verifiedBy: "SYSTEM"
        }
    });

    // Update booking status
    await prisma.booking.update({
        where: { id: payment.bookingId },
        data: {
            status: "PAID",
            paymentStatus: "PAID"
        }
    });

    // Create Tenant record since payment is done
    const booking = await prisma.booking.findUnique({
        where: { id: payment.bookingId },
        include: { room: true }
    });

    if (booking) {
        await prisma.tenant.create({
            data: {
                displayId: `TNT-${Math.floor(Math.random() * 900) + 100}`,
                name: booking.guestName,
                phone: (session as any).phone as string || "TBD",
                email: session.email,
                propertyId: booking.room!.propertyId,
                roomId: booking.roomId!,
                roomNumber: booking.room!.roomNumber,
                roomType: booking.room!.type,
                rent: booking.amount,
                startDate: booking.moveInDate,
                status: "ACTIVE"
            }
        });
    }

    revalidatePath("/dashboard/student");
    revalidatePath("/dashboard/owner/bookings");
    return { success: true };
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";

export async function getProperties(ownerId?: string) {
    const session = await getSession();
    let where: any = {};

    if (ownerId) {
        where.ownerId = ownerId;
    } else if (session?.role === 'OWNER') {
        where.ownerId = (session as any).userId;
    }

    return prisma.property.findMany({
        where,
        include: {
            rooms: true,
            owner: {
                select: {
                    name: true,
                    email: true
                }
            }
        },
        orderBy: {
            updatedAt: 'desc'
        }
    });
}

export async function getPropertyById(id: string) {
    return prisma.property.findUnique({
        where: { id },
        include: {
            rooms: true,
            foodMenu: true,
            owner: {
                select: {
                    name: true,
                    email: true
                }
            }
        }
    });
}

export async function createProperty(formData: FormData) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') {
        throw new Error("Unauthorized");
    }

    const name = formData.get("name") as string;
    const address = formData.get("address") as string;
    const city = formData.get("city") as string;
    const description = formData.get("description") as string;
    const amenities = formData.get("amenities") as string; // Expecting JSON string
    const images = formData.get("images") as string; // Expecting JSON string

    return prisma.property.create({
        data: {
            name,
            address,
            city,
            description,
            amenities,
            images,
            ownerId: (session as any).userId,
        }
    });
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";

export async function getRoomsAction(propertyId?: string) {
    const session = await getSession();
    if (!session || (session.role !== 'OWNER' && session.role !== 'ADMIN')) {
        throw new Error("Unauthorized");
    }

    const where: any = {};
    if (propertyId) {
        where.propertyId = propertyId;
    } else if (session.role === 'OWNER') {
        where.property = { ownerId: (session as any).userId };
    }

    return prisma.room.findMany({
        where,
        include: { property: { select: { name: true } } },
        orderBy: { roomNumber: 'asc' }
    });
}

export async function getAvailableRooms(propertyId?: string) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') {
        throw new Error("Unauthorized");
    }

    const where: any = { availability: { gt: 0 } };
    if (propertyId) {
        where.propertyId = propertyId;
    } else {
        where.property = { ownerId: (session as any).userId };
    }

    return prisma.room.findMany({
        where,
        select: { id: true, roomNumber: true, type: true, price: true }
    });
}

'use server';

import prisma from "@/lib/prisma";

export async function searchProperties(query?: string, filters?: {
    city?: string,
    minPrice?: number,
    maxPrice?: number,
    type?: string
}) {
    const where: any = {};

    if (query) {
        where.OR = [
            { name: { contains: query } },
            { city: { contains: query } },
            { address: { contains: query } }
        ];
    }

    if (filters?.city) {
        where.city = { contains: filters.city };
    }

    const properties = await prisma.property.findMany({
        where,
        include: {
            rooms: {
                select: {
                    price: true,
                    type: true,
                    availability: true
                }
            }
        }
    });

    // Map min price and aggregate ratings (mocked for now as schema doesn't have rating)
    const results = properties.map(p => {
        const prices = p.rooms.map(r => r.price);
        const minPrice = prices.length > 0 ? Math.min(...prices) : 0;

        return {
            ...p,
            minPrice,
            rating: 4.5, // Placeholder
            amenities: JSON.parse(p.amenities || "[]"),
            image: JSON.parse(p.images || "[]")[0] || ""
        };
    });

    // Apply price filters post-fetch for simplicity if needed, or refine Prisma query
    let filteredResults = results;
    if (filters?.minPrice) {
        filteredResults = filteredResults.filter(r => r.minPrice >= filters.minPrice!);
    }
    if (filters?.maxPrice) {
        filteredResults = filteredResults.filter(r => r.minPrice <= filters.maxPrice!);
    }

    return filteredResults;
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function getOwnerStaff() {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const staff = await prisma.ownerStaff.findMany({
        where: { ownerId: (session as any).userId },
        orderBy: { updatedAt: 'desc' }
    });

    // Manually attach action notes for each staff member
    const staffWithNotes = await Promise.all(staff.map(async (s) => {
        const notes = await prisma.actionNote.findMany({
            where: { targetId: s.id, targetType: 'OWNER_STAFF' },
            orderBy: { timestamp: 'desc' }
        });
        return { ...s, actionNotes: notes };
    }));

    return staffWithNotes;
}

export async function addOwnerStaff(data: {
    name: string,
    email: string,
    phone?: string,
    designation: string,
    permissions: string[]
}) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const staff = await prisma.ownerStaff.create({
        data: {
            displayId: `STF-${Math.floor(Math.random() * 9000) + 1000}`,
            ownerId: (session as any).userId,
            name: data.name,
            email: data.email,
            phone: data.phone,
            designation: data.designation,
            permissions: JSON.stringify(data.permissions)
        }
    });

    await prisma.auditLog.create({
        data: {
            action: 'STAFF_ADDED',
            targetId: staff.id,
            targetType: 'OWNER_STAFF',
            details: `${staff.name} (${staff.designation})`,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/owner/staff');
    return staff;
}

export async function updateStaffStatus(id: string, status: 'ACTIVE' | 'REMOVED', reason: string) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') throw new Error("Unauthorized");

    const staff = await prisma.ownerStaff.update({
        where: { id },
        data: { status }
    });

    await prisma.actionNote.create({
        data: {
            targetId: id,
            targetType: 'OWNER_STAFF',
            action: status === 'REMOVED' ? 'REMOVED' : 'RESTORED',
            reason,
            performedBy: 'Owner'
        }
    });

    await prisma.auditLog.create({
        data: {
            action: status === 'REMOVED' ? 'STAFF_REMOVED' : 'STAFF_RESTORED',
            targetId: id,
            targetType: 'OWNER_STAFF',
            details: reason,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/owner/staff');
    return staff;
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function getTeamMembers() {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') {
        throw new Error("Unauthorized");
    }

    return prisma.teamMember.findMany({
        orderBy: { addedOn: 'desc' }
    });
}

export async function addTeamMember(data: { name: string, email: string, phone: string, role: string, permissions: string[] }) {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') {
        throw new Error("Unauthorized");
    }

    const member = await prisma.teamMember.create({
        data: {
            displayId: `ADM-T${Math.floor(Math.random() * 9000) + 1000}`,
            name: data.name,
            email: data.email,
            phone: data.phone,
            role: data.role,
            permissions: JSON.stringify(data.permissions),
            status: 'ACTIVE'
        }
    });

    // Logging
    await prisma.auditLog.create({
        data: {
            action: 'TEAM_MEMBER_ADDED',
            targetId: member.id,
            targetType: 'TEAM_MEMBER',
            details: `${member.name} (${member.role})`,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/admin/team');
    return member;
}

export async function updateTeamMemberStatus(id: string, status: 'ACTIVE' | 'REVOKED', reason: string) {
    const session = await getSession();
    if (!session || session.role !== 'ADMIN') {
        throw new Error("Unauthorized");
    }

    const member = await prisma.teamMember.update({
        where: { id },
        data: { status }
    });

    // Persistent Action Note
    await prisma.actionNote.create({
        data: {
            targetId: id,
            targetType: 'TEAM_MEMBER',
            action: status === 'REVOKED' ? 'REVOKED' : 'RESTORED',
            reason: reason,
            performedBy: (session as any).userId
        }
    });

    // Audit Log
    await prisma.auditLog.create({
        data: {
            action: status === 'REVOKED' ? 'TEAM_ACCESS_REVOKED' : 'TEAM_ACCESS_RESTORED',
            targetId: id,
            targetType: 'TEAM_MEMBER',
            details: reason,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/admin/team');
    return member;
}

'use server';

import prisma from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function getTenants() {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') {
        throw new Error("Unauthorized");
    }

    const userId = (session as any).userId;

    return prisma.tenant.findMany({
        where: {
            property: { ownerId: userId }
        },
        include: {
            rentRecords: {
                orderBy: { createdAt: 'desc' }
            }
        },
        orderBy: { name: 'asc' }
    });
}

export async function markRentAsPaid(recordId: string) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') {
        throw new Error("Unauthorized");
    }

    const today = new Date().toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });

    const record = await prisma.rentRecord.update({
        where: { id: recordId },
        data: {
            paid: true,
            paidOn: today
        }
    });

    // Audit Log
    await prisma.auditLog.create({
        data: {
            action: 'RENT_PAID',
            targetId: record.tenantId,
            targetType: 'TENANT',
            details: `Rent for ${record.month} marked as paid`,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/owner/tenants');
    return record;
}

export async function vacateTenant(tenantId: string) {
    const session = await getSession();
    if (!session || session.role !== 'OWNER') {
        throw new Error("Unauthorized");
    }

    const timestamp = new Date().toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" });

    const tenant = await prisma.tenant.update({
        where: { id: tenantId },
        data: {
            status: 'VACATED',
            vacatedOn: timestamp
        }
    });

    // Audit Log
    await prisma.auditLog.create({
        data: {
            action: 'TENANT_VACATED',
            targetId: tenantId,
            targetType: 'TENANT',
            details: `Vacated on ${timestamp}`,
            performedBy: (session as any).userId
        }
    });

    revalidatePath('/dashboard/owner/tenants');
    return tenant;
}

