const actionLabels: Record<string, { label: string; color: string }> = {
    USER_BANNED: { label: "≡ƒÜ½ User Banned", color: "bg-red-100 text-red-800" },
    USER_UNBANNED: { label: "Γ£à User Unbanned", color: "bg-green-100 text-green-800" },
