export default function AuditLogPage() {
    const [logs, setLogs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [filterAction, setFilterAction] = useState("ALL");

    const fetchLogs = async () => {
        setLoading(true);
        try {
            const data = await getAuditLogs();
            setLogs(data);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchLogs();
    }, []);

    const filtered = logs
        .filter(l => filterAction === "ALL" || l.action === filterAction)
        .filter(l =>
            (l.targetId || "").toLowerCase().includes(search.toLowerCase()) ||
            (l.details || "").toLowerCase().includes(search.toLowerCase()) ||
            (l.performedBy || "").toLowerCase().includes(search.toLowerCase()) ||
            l.action.toLowerCase().includes(search.toLowerCase())
        );

    const uniqueActions = [...new Set(logs.map(l => l.action))];

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-3xl font-bold">Audit Log</h1>
                    <p className="text-muted-foreground">Track all changes made by admin team, owners, and system events.</p>
                </div>
                <Button variant="outline" size="sm" onClick={fetchLogs} disabled={loading}>
                    <RefreshCcw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} /> Refresh
                </Button>
            </div>

            {/* Filters */}
            <div className="flex gap-4 items-center">
                <div className="flex-1 relative">
                    <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                    <Input className="pl-10" placeholder="Search by ID, details, or user..." value={search} onChange={e => setSearch(e.target.value)} />
                </div>
                <select className="border rounded-md p-2 bg-background text-sm" value={filterAction} onChange={e => setFilterAction(e.target.value)}>
                    <option value="ALL">All Actions</option>
                    {uniqueActions.map(a => (
                        <option key={a} value={a}>{actionLabels[a]?.label || a}</option>
                    ))}
                </select>
            </div>

            {/* Log Table */}
            <Card>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-muted border-b">
                                <tr>
                                    <th className="p-4 text-left font-medium">Timestamp</th>
                                    <th className="p-4 text-left font-medium">Action</th>
                                    <th className="p-4 text-left font-medium">Target</th>
                                    <th className="p-4 text-left font-medium">Details</th>
                                    <th className="p-4 text-left font-medium">Performed By</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {loading ? (
                                    <tr><td colSpan={5} className="p-8 text-center animate-pulse">Loading logs...</td></tr>
                                ) : filtered.length === 0 ? (
                                    <tr><td colSpan={5} className="p-8 text-center text-muted-foreground">No audit logs found.</td></tr>
                                ) : (
                                    filtered.map((log) => {
                                        const info = actionLabels[log.action] || { label: log.action, color: "bg-gray-100 text-gray-800" };
                                        return (
                                            <tr key={log.id} className="hover:bg-muted/5">
                                                <td className="p-4 text-xs text-muted-foreground whitespace-nowrap">
                                                    {new Date(log.timestamp).toLocaleString('en-IN', {
                                                        day: '2-digit',
                                                        month: 'short',
                                                        year: 'numeric',
                                                        hour: '2-digit',
                                                        minute: '2-digit',
                                                        hour12: true
                                                    })}
                                                </td>
                                                <td className="p-4">
                                                    <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${info.color}`}>{info.label}</span>
                                                </td>
                                                <td className="p-4 font-mono text-xs">
                                                    {log.targetType ? `${log.targetType}: ` : ""}{log.targetId || "N/A"}
                                                </td>
                                                <td className="p-4 text-sm max-w-xs truncate" title={log.details}>
                                                    {log.details || "-"}
                                                </td>
                                                <td className="p-4 text-sm font-medium">{log.performedBy || "System"}</td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { UserPlus, Trash2, CheckCircle, RefreshCcw } from "lucide-react";
import { getTeamMembers, addTeamMember, updateTeamMemberStatus } from "@/actions/team";

interface ActionNote {
    action: "REVOKED" | "RESTORED";
    reason: string;
    performedBy: string;
    timestamp: string;
}

interface TeamMember {
    id: string;
    name: string;
    email: string;
    phone: string;
    role: string;
    permissions: string; // JSON string from DB
    addedOn: string;
    status: "ACTIVE" | "REVOKED";
    actionNotes?: ActionNote[];
}

const allPermissions = [
    { id: "login_issues", label: "Login & Auth Issues" },
    { id: "payment_failed", label: "Payment Failed / Refunds" },
    { id: "booking_disputes", label: "Booking Disputes" },
    { id: "user_verification", label: "User Verification (KYC)" },
    { id: "ban_users", label: "Ban / Unban Users" },
    { id: "property_moderation", label: "Property Moderation" },
    { id: "support_tickets", label: "Support Tickets" },
    { id: "transaction_view", label: "View Transactions" },
    { id: "reports", label: "Reports & Analytics" },
];

export default function AdminTeamPage() {
    const [team, setTeam] = useState<TeamMember[]>([]);
    const [loading, setLoading] = useState(true);
    const [showAdd, setShowAdd] = useState(false);
    const [newMember, setNewMember] = useState({ name: "", email: "", phone: "", role: "", permissions: [] as string[] });

    const fetchTeam = useCallback(async () => {
        setLoading(true);
        try {
            const data = await getTeamMembers();
            setTeam(data as any);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchTeam();
    }, [fetchTeam]);

    const togglePermission = (permId: string) => {
        setNewMember(prev => ({
            ...prev,
            permissions: prev.permissions.includes(permId)
                ? prev.permissions.filter(p => p !== permId)
                : [...prev.permissions, permId]
        }));
    };

    const handleAddMember = async () => {
        if (!newMember.name || !newMember.email || newMember.permissions.length === 0) {
            alert("Please fill name, email, and select at least one permission.");
            return;
        }

        try {
            await addTeamMember({
                name: newMember.name,
                email: newMember.email,
                phone: newMember.phone || "",
                role: newMember.role || "Team Member",
                permissions: newMember.permissions
            });
            setShowAdd(false);
            setNewMember({ name: "", email: "", phone: "", role: "", permissions: [] });
            fetchTeam();
        } catch (e) {
            alert("Failed to add member.");
        }
    };

    const handleUpdateStatus = async (id: string, currentStatus: string) => {
        const isRevoking = currentStatus === "ACTIVE";
        const reason = prompt(`Reason for ${isRevoking ? "revoking" : "restoring"} access:`);
        if (!reason) return;

        try {
            await updateTeamMemberStatus(id, isRevoking ? "REVOKED" : "ACTIVE", reason);
            fetchTeam();
        } catch (e) {
            alert("Failed to update status.");
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold">Team Access</h1>
                    <p className="text-muted-foreground">Manage admin team members and their permissions.</p>
                </div>
                <div className="flex gap-2">
                    <Button variant="outline" onClick={fetchTeam} disabled={loading}>
                        <RefreshCcw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} /> Refresh
                    </Button>
                    <Button onClick={() => setShowAdd(!showAdd)}>
                        <UserPlus className="h-4 w-4 mr-2" /> Add Member
                    </Button>
                </div>
            </div>

            {showAdd && (
                <Card className="border-primary/30 border-2">
                    <CardContent className="p-6 space-y-4">
                        <h3 className="font-bold text-lg">Add New Team Member</h3>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Full Name *</label>
                                <Input value={newMember.name} onChange={e => setNewMember(p => ({ ...p, name: e.target.value }))} placeholder="John Doe" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Email *</label>
                                <Input value={newMember.email} onChange={e => setNewMember(p => ({ ...p, email: e.target.value }))} placeholder="john@rentpe.in" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Phone</label>
                                <Input value={newMember.phone} onChange={e => setNewMember(p => ({ ...p, phone: e.target.value }))} placeholder="9XXXXXXXXX" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Role Title</label>
                                <Input value={newMember.role} onChange={e => setNewMember(p => ({ ...p, role: e.target.value }))} placeholder="Support Agent" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Permissions *</label>
                            <div className="grid grid-cols-3 gap-2">
                                {allPermissions.map(perm => (
                                    <label key={perm.id} className={`flex items-center gap-2 p-2 rounded border cursor-pointer text-sm ${newMember.permissions.includes(perm.id) ? "bg-primary/10 border-primary" : "hover:bg-muted"}`}>
                                        <input type="checkbox" checked={newMember.permissions.includes(perm.id)} onChange={() => togglePermission(perm.id)} className="accent-primary" />
                                        {perm.label}
                                    </label>
                                ))}
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <Button onClick={handleAddMember} className="bg-green-600 hover:bg-green-700">Add Member</Button>
                            <Button variant="outline" onClick={() => setShowAdd(false)}>Cancel</Button>
                        </div>
                    </CardContent>
                </Card>
            )}

            <Card>
                <CardContent className="p-0">
                    {loading && team.length === 0 ? (
                        <div className="p-8 text-center text-muted-foreground">Loading team members...</div>
                    ) : team.length === 0 ? (
                        <div className="p-8 text-center text-muted-foreground">No team members found. Add one to get started.</div>
                    ) : (
                        <table className="w-full">
                            <thead className="bg-muted border-b">
                                <tr>
                                    <th className="p-4 text-left font-medium">Name</th>
                                    <th className="p-4 text-left font-medium">Role</th>
                                    <th className="p-4 text-left font-medium">Permissions</th>
                                    <th className="p-4 text-left font-medium">Status & History</th>
                                    <th className="p-4 text-left font-medium">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {team.map(m => {
                                    const perms = JSON.parse(m.permissions || "[]");
                                    return (
                                        <tr key={m.id} className={`border-b hover:bg-muted/5 ${m.status === "REVOKED" ? "bg-red-50" : ""}`}>
                                            <td className="p-4">
                                                <div className={`font-medium ${m.status === "REVOKED" ? "line-through text-red-400" : ""}`}>{m.name}</div>
                                                <div className="text-xs text-muted-foreground">{m.email}</div>
                                                <div className="text-[10px] text-muted-foreground">Added: {new Date(m.addedOn).toLocaleDateString()}</div>
                                            </td>
                                            <td className="p-4"><span className="bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs font-bold">{m.role}</span></td>
                                            <td className="p-4">
                                                <div className="flex flex-wrap gap-1">
                                                    {perms.map((p: string) => {
                                                        const perm = allPermissions.find(ap => ap.id === p);
                                                        return <span key={p} className="bg-gray-100 text-gray-700 px-1.5 py-0.5 rounded text-[10px]">{perm?.label || p}</span>;
                                                    })}
                                                </div>
                                            </td>
                                            <td className="p-4">
                                                {m.status === "ACTIVE"
                                                    ? <span className="px-2 py-1 rounded text-xs font-bold bg-green-100 text-green-800">Γ£à Active</span>
                                                    : <span className="px-2 py-1 rounded text-xs font-bold bg-red-100 text-red-800">≡ƒÜ½ Revoked</span>
                                                }
                                            </td>
                                            <td className="p-4">
                                                {m.status === "ACTIVE" ? (
                                                    <Button size="sm" variant="destructive" className="h-8 text-xs" onClick={() => handleUpdateStatus(m.id, m.status)}>
                                                        <Trash2 className="h-3 w-3 mr-1" /> Revoke
                                                    </Button>
                                                ) : (
                                                    <Button size="sm" variant="outline" className="h-8 text-xs border-green-300 text-green-700 hover:bg-green-50" onClick={() => handleUpdateStatus(m.id, m.status)}>
                                                        <CheckCircle className="h-3 w-3 mr-1" /> Restore
                                                    </Button>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { RefreshCcw, Search, ExternalLink } from "lucide-react";
import { getTransactions } from "@/actions/admin";

export default function AdminTransactionsPage() {
    const [transactions, setTransactions] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");

    const fetchTransactions = useCallback(async () => {
        setLoading(true);
        try {
            const data = await getTransactions();
            setTransactions(data);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchTransactions();
    }, [fetchTransactions]);

    const filtered = transactions.filter(txn =>
        txn.id.toLowerCase().includes(search.toLowerCase()) ||
        txn.razorpayOrderId?.toLowerCase().includes(search.toLowerCase()) ||
        txn.booking.user.name.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-3xl font-bold">Transactions</h1>
                    <p className="text-muted-foreground">Global payment history across the platform.</p>
                </div>
                <Button variant="outline" size="sm" onClick={fetchTransactions} disabled={loading}>
                    <RefreshCcw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} /> Refresh
                </Button>
            </div>

            <Card>
                <CardContent className="p-0">
                    <div className="p-4 border-b">
                        <div className="relative">
                            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                            <input
                                className="pl-10 w-full h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                placeholder="Search by ID, Order ID, or User..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                            />
                        </div>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-muted border-b">
                                <tr>
                                    <th className="p-4 text-left font-medium">Transaction / Order ID</th>
                                    <th className="p-4 text-left font-medium">User</th>
                                    <th className="p-4 text-left font-medium">Date</th>
                                    <th className="p-4 text-left font-medium">Method</th>
                                    <th className="p-4 text-left font-medium">Amount</th>
                                    <th className="p-4 text-left font-medium">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {loading ? (
                                    <tr><td colSpan={6} className="p-8 text-center animate-pulse">Loading transactions...</td></tr>
                                ) : filtered.length === 0 ? (
                                    <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">No transactions found.</td></tr>
                                ) : (
                                    filtered.map((txn) => (
                                        <tr key={txn.id} className="hover:bg-muted/5 transition-colors">
                                            <td className="p-4">
                                                <div className="font-mono text-xs text-muted-foreground">ID: {txn.id.split('-')[0]}...</div>
                                                {txn.razorpayOrderId && (
                                                    <div className="text-[10px] text-blue-600 font-medium truncate flex items-center">
                                                        RP_ORD: {txn.razorpayOrderId}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                <div className="font-medium text-sm">{txn.booking.user.name}</div>
                                                <div className="text-[10px] text-muted-foreground">{txn.booking.user.email}</div>
                                            </td>
                                            <td className="p-4 text-xs text-muted-foreground">
                                                {new Date(txn.date).toLocaleDateString('en-IN', {
                                                    day: '2-digit',
                                                    month: 'short',
                                                    year: 'numeric'
                                                })}
                                                <div className="text-[10px]">{new Date(txn.date).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}</div>
                                            </td>
                                            <td className="p-4">
                                                <span className="text-[10px] bg-secondary px-1.5 py-0.5 rounded font-mono uppercase">{txn.method}</span>
                                            </td>
                                            <td className="p-4 font-bold text-sm">
                                                Γé╣{txn.amount.toLocaleString('en-IN')}
                                            </td>
                                            <td className="p-4">
                                                <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${txn.status === 'SUCCESS' || txn.status === 'VERIFIED' ? 'bg-green-100 text-green-800' :
                                                        txn.status === 'PENDING' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'
                                                    }`}>
                                                    {txn.status}
                                                </span>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Ban, CheckCircle, Search, RefreshCcw } from "lucide-react";
import { getUsers, updateUserStatus } from "@/actions/admin";

export default function AdminUsersPage() {
    const [users, setUsers] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [tab, setTab] = useState<"STUDENT" | "OWNER">("STUDENT");
    const [search, setSearch] = useState("");
    const [filterStatus, setFilterStatus] = useState("ALL");

    const fetchUsers = useCallback(async () => {
        setLoading(true);
        try {
            const data = await getUsers();
            setUsers(data);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchUsers();
    }, [fetchUsers]);

    const handleBan = async (userId: string) => {
        const reason = prompt("Reason for ban:");
        if (!reason) return;
        try {
            await updateUserStatus(userId, "BANNED", reason);
            fetchUsers();
        } catch (e) {
            alert("Failed to ban user");
        }
    };

    const handleUnban = async (userId: string) => {
        const reason = prompt("Reason for unbanning:");
        if (!reason) return;
        try {
            await updateUserStatus(userId, "ACTIVE", reason);
            fetchUsers();
        } catch (e) {
            alert("Failed to unban user");
        }
    };

    const studentCount = users.filter(u => u.role === "STUDENT").length;
    const ownerCount = users.filter(u => u.role === "OWNER").length;

    const filtered = users
        .filter(u => u.role === tab)
        .filter(u => filterStatus === "ALL" || u.status === filterStatus)
        .filter(u =>
            u.name.toLowerCase().includes(search.toLowerCase()) ||
            u.email.toLowerCase().includes(search.toLowerCase()) ||
            u.id.includes(search)
        );

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-3xl font-bold">User Management</h1>
                    <p className="text-muted-foreground">Manage students and owners. Ban or unban accounts.</p>
                </div>
                <Button variant="outline" size="sm" onClick={fetchUsers} disabled={loading}>
                    <RefreshCcw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} /> Refresh
                </Button>
            </div>

            {/* Tabs */}
            <div className="flex gap-2">
                <Button variant={tab === "STUDENT" ? "default" : "outline"} onClick={() => setTab("STUDENT")}>
                    Students ({studentCount})
                </Button>
                <Button variant={tab === "OWNER" ? "default" : "outline"} onClick={() => setTab("OWNER")}>
                    Owners ({ownerCount})
                </Button>
            </div>

            {/* Filters */}
            <div className="flex gap-4 items-center">
                <div className="flex-1 relative">
                    <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                    <Input className="pl-10" placeholder="Search by name, email, or ID..." value={search} onChange={e => setSearch(e.target.value)} />
                </div>
                <select className="border rounded-md p-2 bg-background text-sm" value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
                    <option value="ALL">All Status</option>
                    <option value="ACTIVE">Active</option>
                    <option value="VERIFIED">Verified</option>
                    <option value="BANNED">Banned</option>
                </select>
            </div>

            {/* Table */}
            <Card>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-muted border-b">
                                <tr>
                                    <th className="p-4 text-left font-medium">ID</th>
                                    <th className="p-4 text-left font-medium">Name</th>
                                    <th className="p-4 text-left font-medium">Email / Phone</th>
                                    <th className="p-4 text-left font-medium">Status & History</th>
                                    <th className="p-4 text-left font-medium">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {loading ? (
                                    <tr><td colSpan={5} className="p-8 text-center animate-pulse">Loading platform users...</td></tr>
                                ) : filtered.length === 0 ? (
                                    <tr><td colSpan={5} className="p-8 text-center text-muted-foreground">No users found.</td></tr>
                                ) : (
                                    filtered.map(user => (
                                        <tr key={user.id} className={`hover:bg-muted/5 ${user.status === "BANNED" ? "bg-red-50" : ""}`}>
                                            <td className="p-4 font-mono text-xs truncate w-24" title={user.id}>{user.id.split('-')[0]}...</td>
                                            <td className="p-4">
                                                <div className={`font-medium ${user.status === "BANNED" ? "text-red-600 line-through" : ""}`}>{user.name}</div>
                                                <div className="text-[10px] text-muted-foreground">
                                                    Joined: {new Date(user.createdAt).toLocaleDateString()}
                                                </div>
                                            </td>
                                            <td className="p-4 text-sm">
                                                <div>{user.email}</div>
                                                <div className="text-xs text-muted-foreground">{user.phone || "No Phone"}</div>
                                            </td>
                                            <td className="p-4">
                                                {user.status === "BANNED" ? (
                                                    <span className="px-2 py-1 rounded text-[10px] font-bold bg-red-100 text-red-800 uppercase">≡ƒÜ½ Banned</span>
                                                ) : (
                                                    <span className="px-2 py-1 rounded text-[10px] font-bold bg-green-100 text-green-800 uppercase">Γ£à {user.status}</span>
                                                )}
                                                {/* Persistent action history */}
                                                {user.actionNotes && user.actionNotes.length > 0 && (
                                                    <div className="mt-2 space-y-1 max-h-32 overflow-y-auto">
                                                        {user.actionNotes.map((note: any) => (
                                                            <div key={note.id} className={`text-[10px] p-1.5 rounded border ${note.action === "BANNED" ? "bg-red-50 border-red-200 text-red-700" : "bg-green-50 border-green-200 text-green-700"}`}>
                                                                <div className="font-bold">{note.action === "BANNED" ? "≡ƒÜ½ Banned" : "Γ£à Unbanned"}</div>
                                                                <div className="truncate" title={note.reason}>Reason: {note.reason}</div>
                                                                <div className="text-muted-foreground">By: {note.performedBy} ΓÇó {new Date(note.timestamp).toLocaleDateString()}</div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                {user.status === "BANNED" ? (
                                                    <Button size="sm" variant="outline" className="h-8 text-xs border-green-300 text-green-700 hover:bg-green-50" onClick={() => handleUnban(user.id)}>
                                                        <CheckCircle className="h-3 w-3 mr-1" /> Unban
                                                    </Button>
                                                ) : (
                                                    <Button size="sm" variant="destructive" className="h-8 text-xs" onClick={() => handleBan(user.id)}>
                                                        <Ban className="h-3 w-3 mr-1" /> Ban
                                                    </Button>
                                                )}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Eye, Clock } from "lucide-react";
import { useEffect, useState } from "react";
import { getBookings, approveBooking, rejectBooking as rejectBookingAction } from "@/actions/bookings";
import { getAvailableRooms } from "@/actions/rooms";

export default function BookingsPage() {
    const [bookings, setBookings] = useState<any[]>([]);
    const [rooms, setRooms] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [approveModal, setApproveModal] = useState<any>(null);
    const [selectedRoomId, setSelectedRoomId] = useState("");

    const fetchData = async () => {
        setLoading(true);
        try {
            const [bookingData, roomData] = await Promise.all([
                getBookings(),
                getAvailableRooms()
            ]);
            setBookings(bookingData);
            setRooms(roomData);
        } catch (error) {
            console.error("Failed to fetch data:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const confirmApprove = async () => {
        if (!selectedRoomId) { alert("Please select a room number."); return; }
        const room = rooms.find(r => r.id === selectedRoomId);
        if (!room) return;

        try {
            await approveBooking(approveModal.id, {
                roomId: room.id,
                amount: `Γé╣${room.price.toLocaleString()}`,
                occupancy: room.type,
                roomAssigned: `${room.roomNumber} (${room.type})`
            });
            setApproveModal(null);
            fetchData();
        } catch (error) {
            alert("Approval failed.");
        }
    };

    const handleReject = async (bookingId: string) => {
        if (!confirm("Reject this booking request?")) return;
        try {
            await rejectBookingAction(bookingId);
            fetchData();
        } catch (error) {
            alert("Rejection failed.");
        }
    };

    const pendingCount = bookings.filter(b => b.status === "PENDING_APPROVAL").length;

    if (loading) return <div className="p-8 text-center text-muted-foreground">Loading bookings...</div>;

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold">Bookings</h1>
                    <p className="text-muted-foreground">Manage new requests and verify guest details.</p>
                </div>
                {pendingCount > 0 && (
                    <span className="bg-red-500 text-white px-3 py-1 rounded-full text-sm font-bold animate-pulse">
                        {pendingCount} New Request{pendingCount > 1 ? "s" : ""}
                    </span>
                )}
            </div>

            <Card>
                <CardContent className="p-0 text-sm md:text-base">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-muted border-b">
                                <tr>
                                    <th className="p-4 text-left font-medium">Booking ID</th>
                                    <th className="p-4 text-left font-medium">Guest Name</th>
                                    <th className="p-4 text-left font-medium">Room</th>
                                    <th className="p-4 text-left font-medium">Requested On</th>
                                    <th className="p-4 text-left font-medium">Status</th>
                                    <th className="p-4 text-left font-medium">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {bookings.map((booking) => (
                                    <tr key={booking.id} className={`border-b hover:bg-muted/5 ${booking.status === "PENDING_APPROVAL" ? "bg-red-50/50" : ""}`}>
                                        <td className="p-4 font-medium">{booking.displayId}</td>
                                        <td className="p-4 font-medium">{booking.guestName}</td>
                                        <td className="p-4">
                                            <div className="flex flex-col">
                                                <span>{booking.roomAssigned || "Not Allocated"}</span>
                                                <span className="text-[10px] text-muted-foreground uppercase">{booking.occupancy}</span>
                                            </div>
                                        </td>
                                        <td className="p-4 text-muted-foreground text-xs italic">
                                            {new Date(booking.createdAt).toLocaleString()}
                                        </td>
                                        <td className="p-4">
                                            {booking.status === "PENDING_APPROVAL" && (
                                                <span className="px-2 py-1 rounded text-[10px] font-bold bg-red-100 text-red-800">≡ƒö┤ NEW</span>
                                            )}
                                            {(booking.status === "APPROVED_PAYMENT_PENDING" || booking.status === "APPROVED") && (
                                                <span className="px-2 py-1 rounded text-[10px] font-bold bg-yellow-100 text-yellow-800">WAITING PAYMENT</span>
                                            )}
                                            {booking.status === "PAID" && (
                                                <span className="px-2 py-1 rounded text-[10px] font-bold bg-green-100 text-green-800">PAID</span>
                                            )}
                                            {booking.status === "CONFIRMED" && (
                                                <span className="px-2 py-1 rounded text-[10px] font-bold bg-blue-100 text-blue-800">CONFIRMED</span>
                                            )}
                                            {booking.status === "REJECTED" && (
                                                <span className="px-2 py-1 rounded text-[10px] font-bold bg-gray-100 text-gray-800">REJECTED</span>
                                            )}
                                        </td>
                                        <td className="p-4">
                                            <div className="flex space-x-2">
                                                {booking.status === "PENDING_APPROVAL" && (
                                                    <>
                                                        <Button size="sm" className="bg-green-600 hover:bg-green-700 h-8 text-xs" onClick={() => {
                                                            setApproveModal(booking);
                                                            // Auto-select first matching room type if possible
                                                            const match = rooms.find(r => booking.occupancy.includes(r.type));
                                                            setSelectedRoomId(match?.id || rooms[0]?.id || "");
                                                        }}>
                                                            Accept
                                                        </Button>
                                                        <Button size="sm" variant="destructive" className="h-8 text-xs" onClick={() => handleReject(booking.id)}>
                                                            Reject
                                                        </Button>
                                                    </>
                                                )}
                                                <Button variant="outline" size="sm" className="h-8 w-8 p-0">
                                                    <Eye className="h-4 w-4 text-muted-foreground" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>

            {/* Approve Modal */}
            {approveModal && (
                <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-md">
                        <h2 className="text-xl font-bold mb-2">Accept Booking</h2>
                        <p className="text-sm text-muted-foreground mb-4">Select a room to allocate for <strong>{approveModal.guestName}</strong>.</p>

                        <div className="space-y-4">
                            <div>
                                <label className="text-xs font-bold uppercase text-muted-foreground block mb-1">Available Rooms</label>
                                <select
                                    className="w-full border rounded-md p-2 bg-background"
                                    value={selectedRoomId}
                                    onChange={(e) => setSelectedRoomId(e.target.value)}
                                >
                                    <option value="" disabled>Select a room...</option>
                                    {rooms.map(room => (
                                        <option key={room.id} value={room.id}>
                                            Room {room.roomNumber} ΓÇö {room.type} ΓÇö Γé╣{room.price.toLocaleString()}
                                        </option>
                                    ))}
                                </select>
                                {rooms.length === 0 && <p className="text-xs text-red-500 mt-1">No vacant rooms available!</p>}
                            </div>

                            {selectedRoomId && (
                                <div className="bg-muted/50 p-3 rounded text-sm border">
                                    <p><strong>Offer:</strong> {rooms.find(r => r.id === selectedRoomId)?.roomNumber} ({rooms.find(r => r.id === selectedRoomId)?.type})</p>
                                    <p className="mt-1"><strong>Price:</strong> Γé╣{rooms.find(r => r.id === selectedRoomId)?.price.toLocaleString()}/mo</p>
                                </div>
                            )}
                        </div>

                        <div className="flex gap-3 mt-8">
                            <Button className="flex-1 bg-green-600 hover:bg-green-700" onClick={confirmApprove} disabled={!selectedRoomId}>
                                Confirm Accept
                            </Button>
                            <Button variant="ghost" className="flex-1" onClick={() => setApproveModal(null)}>
                                Cancel
                            </Button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useState, useEffect } from "react";
import { Plus, Trash2, Utensils, Save } from "lucide-react";
import { getFoodMenu, updateFoodMenu } from "@/actions/ops";
import { getProperties } from "@/actions/properties";

const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

export default function FoodMenuPage() {
    const [properties, setProperties] = useState<any[]>([]);
    const [selectedPropertyId, setSelectedPropertyId] = useState<string>("");
    const [menu, setMenu] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        const fetchInitial = async () => {
            const props = await getProperties();
            setProperties(props);
            if (props.length > 0) {
                setSelectedPropertyId(props[0].id);
            } else {
                setLoading(false);
            }
        };
        fetchInitial();
    }, []);

    useEffect(() => {
        if (selectedPropertyId) {
            fetchMenu();
        }
    }, [selectedPropertyId]);

    const fetchMenu = async () => {
        setLoading(true);
        try {
            const data = await getFoodMenu(selectedPropertyId);
            // Ensure all days are present and aggregate meals
            const aggregatedMenu = DAYS.map(dayName => {
                const dayMeals = data.filter(m => m.dayOfWeek === dayName);
                return {
                    day: dayName,
                    breakfast: dayMeals.find(m => m.mealType === 'Breakfast')?.items || "",
                    lunch: dayMeals.find(m => m.mealType === 'Lunch')?.items || "",
                    dinner: dayMeals.find(m => m.mealType === 'Dinner')?.items || ""
                };
            });
            setMenu(aggregatedMenu);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleUpdate = (day: string, type: 'breakfast' | 'lunch' | 'dinner', val: string) => {
        setMenu(prev => prev.map(m => m.day === day ? { ...m, [type]: val } : m));
    };

    const handleSave = async (day: string) => {
        const item = menu.find(m => m.day === day);
        if (!item) return;

        setSaving(true);
        try {
            await updateFoodMenu(selectedPropertyId, day, {
                breakfast: item.breakfast,
                lunch: item.lunch,
                dinner: item.dinner
            });
            alert(`Menu for ${day} saved!`);
        } catch (error) {
            alert("Failed to save menu.");
        } finally {
            setSaving(false);
        }
    };

    if (loading) return <div className="p-8 text-center text-muted-foreground">Loading menu...</div>;

    if (properties.length === 0) {
        return (
            <div className="p-12 text-center">
                <h2 className="text-xl font-bold">No Properties Found</h2>
                <p className="text-muted-foreground mt-2">Add a property first to manage its food menu.</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold">Food Menu</h1>
                    <p className="text-muted-foreground">Weekly meal plan for residents.</p>
                </div>
                <div className="flex items-center gap-4">
                    <select
                        className="bg-background border rounded px-3 py-2 text-sm"
                        value={selectedPropertyId}
                        onChange={(e) => setSelectedPropertyId(e.target.value)}
                    >
                        {properties.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                    </select>
                </div>
            </div>

            <div className="grid gap-6">
                {menu.map((dayItem) => (
                    <Card key={dayItem.day}>
                        <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
                            <CardTitle className="text-lg font-bold flex items-center gap-2">
                                <Utensils className="h-4 w-4 text-primary" />
                                {dayItem.day}
                            </CardTitle>
                            <Button size="sm" onClick={() => handleSave(dayItem.day)} disabled={saving}>
                                <Save className="h-4 w-4 mr-2" /> Save Day
                            </Button>
                        </CardHeader>
                        <CardContent>
                            <div className="grid md:grid-cols-3 gap-4">
                                <div className="space-y-2">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Breakfast</label>
                                    <Input
                                        placeholder="e.g. Poha, Tea"
                                        value={dayItem.breakfast || ""}
                                        onChange={(e) => handleUpdate(dayItem.day, 'breakfast', e.target.value)}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Lunch</label>
                                    <Input
                                        placeholder="e.g. Thali, Rice"
                                        value={dayItem.lunch || ""}
                                        onChange={(e) => handleUpdate(dayItem.day, 'lunch', e.target.value)}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Dinner</label>
                                    <Input
                                        placeholder="e.g. Roti, Sabzi"
                                        value={dayItem.dinner || ""}
                                        onChange={(e) => handleUpdate(dayItem.day, 'dinner', e.target.value)}
                                    />
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>
        </div>
    );
}

