"use client";

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { UserPlus, Trash2, CheckCircle } from "lucide-react";
import { getOwnerStaff, addOwnerStaff, updateStaffStatus } from "@/actions/staff";

const ownerPermissionsList = [
    { id: "view_bookings", label: "View Bookings" },
    { id: "approve_bookings", label: "Approve / Reject Bookings" },
    { id: "manage_tenants", label: "Manage Tenants" },
    { id: "mark_rent", label: "Mark Rent Paid" },
    { id: "vacate_tenant", label: "Vacate Tenants" },
    { id: "edit_rooms", label: "Edit Room Allocation" },
    { id: "view_payments", label: "View Payments" },
    { id: "food_menu", label: "Manage Food Menu" },
    { id: "support", label: "Handle Support Tickets" },
];

export default function OwnerStaffPage() {
    const [staff, setStaff] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [showAdd, setShowAdd] = useState(false);
    const [form, setForm] = useState({ name: "", email: "", phone: "", designation: "", permissions: [] as string[] });

    const fetchStaff = async () => {
        setLoading(true);
        try {
            const data = await getOwnerStaff();
            setStaff(data);
        } catch (error) {
            console.error("Failed to fetch staff:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchStaff();
    }, []);

    const togglePerm = (id: string) => {
        setForm(prev => ({
            ...prev,
            permissions: prev.permissions.includes(id) ? prev.permissions.filter(p => p !== id) : [...prev.permissions, id]
        }));
    };

    const handleAddStaff = async () => {
        if (!form.name || !form.email || form.permissions.length === 0) {
            alert("Fill name, email, and select at least one permission.");
            return;
        }
        try {
            await addOwnerStaff(form);
            setShowAdd(false);
            setForm({ name: "", email: "", phone: "", designation: "", permissions: [] });
            fetchStaff();
        } catch (error) {
            alert("Failed to add staff member.");
        }
    };

    const handleRemoveStaff = async (id: string) => {
        const reason = prompt("Reason for removing this staff member:");
        if (!reason) return;
        try {
            await updateStaffStatus(id, "REMOVED", reason);
            fetchStaff();
        } catch (error) {
            alert("Failed to remove staff.");
        }
    };

    const handleRestoreStaff = async (id: string) => {
        const reason = prompt("Reason for restoring this staff member:");
        if (!reason) return;
        try {
            await updateStaffStatus(id, "ACTIVE", reason);
            fetchStaff();
        } catch (error) {
            alert("Failed to restore staff.");
        }
    };

    if (loading) return <div className="p-8 text-center text-muted-foreground">Loading staff...</div>;

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold">My Staff</h1>
                    <p className="text-muted-foreground">Add subordinates and control what they can access.</p>
                </div>
                <Button onClick={() => setShowAdd(!showAdd)}>
                    <UserPlus className="h-4 w-4 mr-2" /> Add Staff
                </Button>
            </div>

            {showAdd && (
                <Card className="border-primary/30 border-2">
                    <CardContent className="p-6 space-y-4">
                        <h3 className="font-bold text-lg">Add New Staff Member</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Full Name *</label>
                                <Input value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} placeholder="Name" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Email *</label>
                                <Input value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} placeholder="email@pg.com" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Phone</label>
                                <Input value={form.phone} onChange={e => setForm(p => ({ ...p, phone: e.target.value }))} placeholder="9XXXXXXXXX" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-sm font-medium">Designation</label>
                                <Input value={form.designation} onChange={e => setForm(p => ({ ...p, designation: e.target.value }))} placeholder="Property Manager" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Authorized Permissions *</label>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                                {ownerPermissionsList.map(perm => (
                                    <label key={perm.id} className={`flex items-center gap-2 p-2 rounded border cursor-pointer text-xs ${form.permissions.includes(perm.id) ? "bg-primary/10 border-primary" : "hover:bg-muted"}`}>
                                        <input type="checkbox" checked={form.permissions.includes(perm.id)} onChange={() => togglePerm(perm.id)} className="accent-primary" />
                                        {perm.label}
                                    </label>
                                ))}
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <Button onClick={handleAddStaff} className="bg-green-600 hover:bg-green-700">Add Staff</Button>
                            <Button variant="outline" onClick={() => setShowAdd(false)}>Cancel</Button>
                        </div>
                    </CardContent>
                </Card>
            )}

            {/* Staff Table */}
            <Card>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-muted border-b">
                                <tr>
                                    <th className="p-4 text-left font-medium">ID</th>
                                    <th className="p-4 text-left font-medium">Name</th>
                                    <th className="p-4 text-left font-medium">Designation</th>
                                    <th className="p-4 text-left font-medium">Authorized For</th>
                                    <th className="p-4 text-left font-medium">Status & History</th>
                                    <th className="p-4 text-left font-medium">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {staff.map((s: any) => {
                                    const perms = JSON.parse(s.permissions || "[]");
                                    return (
                                        <tr key={s.id} className={`border-b hover:bg-muted/5 ${s.status === "REMOVED" ? "bg-red-50/50" : ""}`}>
                                            <td className="p-4 font-mono text-xs">{s.displayId}</td>
                                            <td className="p-4">
                                                <div className={`font-medium ${s.status === "REMOVED" ? "line-through text-red-400" : ""}`}>{s.name}</div>
                                                <div className="text-[10px] text-muted-foreground">{s.email} ΓÇó {s.phone}</div>
                                                <div className="text-[10px] text-muted-foreground italic">Added: {s.addedOn}</div>
                                            </td>
                                            <td className="p-4"><span className="bg-purple-100 text-purple-800 px-2 py-0.5 rounded text-[10px] font-bold uppercase">{s.designation}</span></td>
                                            <td className="p-4">
                                                <div className="flex flex-wrap gap-1">
                                                    {perms.map((p: string) => {
                                                        const perm = ownerPermissionsList.find(op => op.id === p);
                                                        return <span key={p} className="bg-gray-100 text-gray-700 px-1.5 py-0.5 rounded text-[10px]">{perm?.label || p}</span>;
                                                    })}
                                                </div>
                                            </td>
                                            <td className="p-4">
                                                {s.status === "ACTIVE"
                                                    ? <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-green-100 text-green-800 uppercase">Γ£à Active</span>
                                                    : <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-800 uppercase">≡ƒÜ½ Removed</span>
                                                }
                                                {s.actionNotes?.length > 0 && (
                                                    <div className="mt-2 space-y-1 max-h-32 overflow-y-auto">
                                                        {s.actionNotes.map((note: any, i: number) => (
                                                            <div key={i} className={`text-[9px] p-1 rounded border ${note.action === "REMOVED" ? "bg-red-50 border-red-200 text-red-700" : "bg-green-50 border-green-200 text-green-700"}`}>
                                                                <div className="font-bold uppercase">{note.action === "REMOVED" ? "≡ƒÜ½ Removed" : "Γ£à Restored"}</div>
                                                                <div>Reason: {note.reason}</div>
                                                                <div>{note.timestamp}</div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                {s.status === "ACTIVE" ? (
                                                    <Button size="sm" variant="destructive" className="h-7 text-[10px]" onClick={() => handleRemoveStaff(s.id)}>
                                                        <Trash2 className="h-3 w-3 mr-1" /> Remove
                                                    </Button>
                                                ) : (
                                                    <Button size="sm" variant="outline" className="h-7 text-[10px] border-green-300 text-green-700 hover:bg-green-50" onClick={() => handleRestoreStaff(s.id)}>
                                                        <CheckCircle className="h-3 w-3 mr-1" /> Restore
                                                    </Button>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                    {staff.length === 0 && <div className="p-8 text-center text-muted-foreground">No staff members added yet.</div>}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { Fragment, useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { getTenants, markRentAsPaid, vacateTenant as vacateTenantAction } from "@/actions/tenants";

export default function TenantsPage() {
    const [tenants, setTenants] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [filterType, setFilterType] = useState("ALL");
    const [filterPayment, setFilterPayment] = useState("ALL");
    const [expandedTenant, setExpandedTenant] = useState<string | null>(null);

    const currentMonth = "Feb 2024";

    const fetchTenants = async () => {
        setLoading(true);
        try {
            const data = await getTenants();
            setTenants(data);
        } catch (error) {
            console.error("Failed to fetch tenants:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchTenants();
    }, []);

    const markAsPaid = async (recordId: string) => {
        try {
            await markRentAsPaid(recordId);
            await fetchTenants();
        } catch (error) {
            alert("Failed to mark rent as paid.");
        }
    };

    const vacateTenant = async (tenantId: string) => {
        if (!confirm("Mark this tenant as vacated? This will free up their room.")) return;
        try {
            await vacateTenantAction(tenantId);
            await fetchTenants();
        } catch (error) {
            alert("Failed to vacate tenant.");
        }
    };

    const filteredTenants = tenants.filter(t => {
        const matchSearch = t.name.toLowerCase().includes(search.toLowerCase()) || t.roomNumber.includes(search) || t.displayId.includes(search);
        const matchType = filterType === "ALL" || t.roomType === filterType;
        const latestRent = t.rentRecords.find((r: any) => r.month === currentMonth);
        const isPaid = latestRent?.paid ?? false;
        const matchPayment = filterPayment === "ALL"
            || (filterPayment === "PAID" && isPaid)
            || (filterPayment === "UNPAID" && !isPaid)
            || (filterPayment === "VACATED" && t.status === "VACATED");
        if (filterPayment === "VACATED") return matchSearch && matchType && t.status === "VACATED";
        if (filterPayment !== "ALL" && t.status === "VACATED") return false;
        return matchSearch && matchType && matchPayment;
    });

    const unpaidCount = tenants.filter(t => {
        const latestRent = t.rentRecords.find((r: any) => r.month === currentMonth);
        return !latestRent?.paid && t.status !== "VACATED";
    }).length;

    if (loading) {
        return <div className="p-8 text-center">Loading tenants...</div>;
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold">Tenants</h1>
                    <p className="text-muted-foreground">Manage active tenants and track monthly rent.</p>
                </div>
                <div className="flex gap-2 items-center">
                    <span className="text-sm text-muted-foreground">Total: <strong>{tenants.length}</strong></span>
                    {unpaidCount > 0 && (
                        <span className="bg-red-500 text-white px-3 py-1 rounded-full text-sm font-bold">
                            {unpaidCount} Unpaid
                        </span>
                    )}
                </div>
            </div>

            {/* Filters */}
            <Card>
                <CardContent className="p-4">
                    <div className="flex flex-wrap gap-4 items-center">
                        <div className="flex-1 min-w-[200px]">
                            <Input
                                placeholder="Search by name, room, or ID..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                            />
                        </div>
                        <div>
                            <select
                                className="border rounded-md p-2 bg-background text-sm"
                                value={filterType}
                                onChange={(e) => setFilterType(e.target.value)}
                            >
                                <option value="ALL">All Room Types</option>
                                <option value="Single">Single</option>
                                <option value="Double">Double</option>
                                <option value="Triple">Triple</option>
                            </select>
                        </div>
                        <div>
                            <select
                                className="border rounded-md p-2 bg-background text-sm"
                                value={filterPayment}
                                onChange={(e) => setFilterPayment(e.target.value)}
                            >
                                <option value="ALL">All Payment Status</option>
                                <option value="PAID">Rent Paid</option>
                                <option value="UNPAID">Rent Unpaid</option>
                                <option value="VACATED">Vacated</option>
                            </select>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Tenants Table */}
            <Card>
                <CardContent className="p-0">
                    <table className="w-full">
                        <thead className="bg-muted border-b">
                            <tr>
                                <th className="p-4 text-left font-medium">Tenant ID</th>
                                <th className="p-4 text-left font-medium">Name</th>
                                <th className="p-4 text-left font-medium">Room</th>
                                <th className="p-4 text-left font-medium">Start Date</th>
                                <th className="p-4 text-left font-medium">Monthly Rent</th>
                                <th className="p-4 text-left font-medium">{currentMonth} Status</th>
                                <th className="p-4 text-left font-medium">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredTenants.map((tenant) => {
                                const latestRent = tenant.rentRecords.find((r: any) => r.month === currentMonth);
                                const isPaid = latestRent?.paid ?? false;

                                return (
                                    <Fragment key={tenant.id}>
                                        <tr className={`border-b hover:bg-muted/5 ${tenant.status === "VACATED" ? "bg-gray-100 opacity-60" : !isPaid ? "bg-red-50" : ""}`}>
                                            <td className="p-4 font-medium">{tenant.displayId}</td>
                                            <td className={`p-4 font-medium ${tenant.status === "VACATED" ? "line-through text-gray-400" : !isPaid ? "text-red-600" : ""}`}>
                                                {tenant.name}
                                                {tenant.status === "VACATED" && <span className="ml-2 text-xs">≡ƒÅá Vacated</span>}
                                                {tenant.status !== "VACATED" && !isPaid && <span className="ml-2 text-xs">ΓÜá∩╕Å</span>}
                                            </td>
                                            <td className="p-4">{tenant.roomNumber} ({tenant.roomType})</td>
                                            <td className="p-4 text-sm text-muted-foreground">{tenant.startDate}</td>
                                            <td className="p-4 font-bold">{tenant.rent}</td>
                                            <td className="p-4">
                                                {tenant.status === "VACATED" ? (
                                                    <div>
                                                        <span className="px-2 py-1 rounded text-xs font-bold bg-gray-200 text-gray-600">≡ƒÅá Vacated</span>
                                                        <p className="text-[10px] text-gray-400 mt-1">{tenant.vacatedOn}</p>
                                                    </div>
                                                ) : isPaid ? (
                                                    <span className="px-2 py-1 rounded text-xs font-bold bg-green-100 text-green-800">
                                                        Γ£à Paid ({latestRent?.paidOn})
                                                    </span>
                                                ) : (
                                                    <span className="px-2 py-1 rounded text-xs font-bold bg-red-100 text-red-800 animate-pulse">
                                                        ≡ƒö┤ Unpaid
                                                    </span>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                <div className="flex space-x-2">
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="h-8 text-xs"
                                                        onClick={() => setExpandedTenant(expandedTenant === tenant.id ? null : tenant.id)}
                                                    >
                                                        {expandedTenant === tenant.id ? "Hide History" : "Rent History"}
                                                    </Button>
                                                    {tenant.status !== "VACATED" && !isPaid && latestRent && (
                                                        <Button
                                                            size="sm"
                                                            className="h-8 text-xs bg-green-600 hover:bg-green-700"
                                                            onClick={() => markAsPaid(latestRent.id)}
                                                        >
                                                            Mark Paid
                                                        </Button>
                                                    )}
                                                    {tenant.status !== "VACATED" && (
                                                        <Button
                                                            size="sm"
                                                            variant="outline"
                                                            className="h-8 text-xs border-orange-300 text-orange-600 hover:bg-orange-50"
                                                            onClick={() => vacateTenant(tenant.id)}
                                                        >
                                                            Vacate
                                                        </Button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                        {expandedTenant === tenant.id && (
                                            <tr key={tenant.id + "-history"}>
                                                <td colSpan={7} className="p-0">
                                                    <div className="bg-muted/30 p-4 border-b">
                                                        <h4 className="font-medium mb-2 text-sm">≡ƒôï Rent History ΓÇö {tenant.name}</h4>
                                                        <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                                                            {tenant.rentRecords.map((r: any) => (
                                                                <div
                                                                    key={r.id}
                                                                    className={`p-3 rounded-lg border text-sm ${r.paid ? "bg-green-50 border-green-200" : "bg-red-50 border-red-200"}`}
                                                                >
                                                                    <div className="font-medium">{r.month}</div>
                                                                    <div className="text-xs mt-1">{r.amount}</div>
                                                                    <div className={`text-xs mt-1 font-bold ${r.paid ? "text-green-700" : "text-red-700"}`}>
                                                                        {r.paid ? `Γ£à Paid on ${r.paidOn}` : "≡ƒö┤ Unpaid"}
                                                                    </div>
                                                                </div>
                                                            ))}
                                                        </div>
                                                    </div>
                                                </td>
                                            </tr>
                                        )}
                                    </Fragment>
                                );
                            })}
                        </tbody>
                    </table>
                    {filteredTenants.length === 0 && (
                        <div className="p-8 text-center text-muted-foreground">No tenants match your filters.</div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useEffect, useState } from "react";
import { getOwnerTickets, resolveTicket, replyToTicket } from "@/actions/ops";
import { MessageSquare, CheckCircle, Clock, AlertCircle } from "lucide-react";

export default function OwnerTicketsPage() {
    const [tickets, setTickets] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    const fetchTickets = async () => {
        setLoading(true);
        try {
            const data = await getOwnerTickets();
            setTickets(data);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchTickets();
    }, []);

    const handleResolve = async (id: string) => {
        if (!confirm(`Mark ticket as resolved?`)) return;
        try {
            await resolveTicket(id);
            fetchTickets();
        } catch (error) {
            alert("Failed to resolve ticket.");
        }
    };

    const handleReply = async (id: string) => {
        const message = prompt(`Enter your reply:`);
        if (!message) return;
        try {
            await replyToTicket(id, message);
            fetchTickets();
        } catch (error) {
            alert("Failed to send reply.");
        }
    };

    if (loading) return <div className="p-8 text-center text-muted-foreground">Loading tickets...</div>;

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold">Support Tickets</h1>
                    <p className="text-muted-foreground">Manage resident complaints and requests.</p>
                </div>
                <Button variant="outline" onClick={fetchTickets}>Refresh</Button>
            </div>

            <div className="grid gap-4">
                {tickets.map((ticket) => {
                    const replies = JSON.parse(ticket.replies || "[]");
                    return (
                        <Card key={ticket.id} className={ticket.status === 'RESOLVED' ? 'opacity-70' : ''}>
                            <CardHeader className="pb-2 text-primary font-semibold">
                                <div className="flex justify-between items-start">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            <CardTitle className="text-lg">{ticket.category}</CardTitle>
                                            <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${ticket.status === 'OPEN' ? 'bg-green-100 text-green-800' :
                                                    ticket.status === 'IN_PROGRESS' ? 'bg-yellow-100 text-yellow-800' :
                                                        'bg-gray-100 text-gray-800'
                                                }`}>
                                                {ticket.status}
                                            </span>
                                            <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${ticket.priority === 'HIGH' ? 'bg-red-100 text-red-800' : 'bg-blue-100 text-blue-800'
                                                }`}>
                                                {ticket.priority} Priority
                                            </span>
                                        </div>
                                        <CardDescription className="text-xs">
                                            Ticket ID: <span className="font-mono">{ticket.displayId}</span> ΓÇó
                                            Student: {ticket.user?.name} ΓÇó
                                            {new Date(ticket.createdAt).toLocaleDateString()}
                                        </CardDescription>
                                    </div>
                                    <div className="p-2 rounded-full bg-muted">
                                        {ticket.status === 'RESOLVED' ? <CheckCircle className="h-5 w-5 text-green-600" /> : <Clock className="h-5 w-5 text-yellow-600" />}
                                    </div>
                                </div>
                            </CardHeader>
                            <CardContent>
                                <div className="p-4 rounded bg-muted/30 border mb-4">
                                    <p className="text-sm font-medium">Issue Description:</p>
                                    <p className="text-sm text-foreground mt-1">{ticket.description}</p>
                                </div>

                                {replies.length > 0 && (
                                    <div className="space-y-3 mb-4">
                                        <p className="text-xs font-bold uppercase text-muted-foreground">Conversation History</p>
                                        {replies.map((r: any, idx: number) => (
                                            <div key={idx} className={`p-2 rounded text-xs ${r.sender === 'OWNER' ? 'bg-primary/5 border-l-2 border-primary ml-4' : 'bg-muted border-l-2 border-muted-foreground mr-4'}`}>
                                                <div className="flex justify-between items-center mb-1">
                                                    <span className="font-bold">{r.sender === 'OWNER' ? 'You' : 'Student'}</span>
                                                    <span className="opacity-60">{new Date(r.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                                </div>
                                                <p>{r.message}</p>
                                            </div>
                                        ))}
                                    </div>
                                )}

                                <div className="flex space-x-2 pt-2 border-t">
                                    {ticket.status !== 'RESOLVED' && (
                                        <Button variant="default" size="sm" className="bg-green-600 hover:bg-green-700" onClick={() => handleResolve(ticket.id)}>
                                            <CheckCircle className="h-4 w-4 mr-2" /> Mark Resolved
                                        </Button>
                                    )}
                                    <Button variant="outline" size="sm" onClick={() => handleReply(ticket.id)}>
                                        <MessageSquare className="h-4 w-4 mr-2" /> Reply
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    );
                })}
                {tickets.length === 0 && (
                    <div className="p-12 text-center border-2 border-dashed rounded-xl text-muted-foreground">
                        <AlertCircle className="h-8 w-8 mx-auto mb-2 opacity-50" />
                        No support tickets found. Everything looks good!
                    </div>
                )}
            </div>
        </div>
    );
}

