"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Lock, CreditCard, Banknote, Smartphone, Building, CheckCircle } from "lucide-react";
import { useState, useEffect, Suspense } from "react";
import { cn } from "@/components/ui/button";
import { useRouter, useSearchParams } from "next/navigation";
import { getBookingById } from "@/actions/bookings";
import { createRazorpayOrder, verifyPayment } from "@/actions/payments";
import Script from "next/script";

function PaymentPortal() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const id = searchParams.get("id");

    const [method, setMethod] = useState("upi");
    const [isPaying, setIsPaying] = useState(false);
    const [isPaid, setIsPaid] = useState(false);
    const [loading, setLoading] = useState(true);
    const [booking, setBooking] = useState<any>(null);

    useEffect(() => {
        if (!id) {
            router.push("/dashboard/student");
            return;
        }
        const fetchBooking = async () => {
            try {
                const data = await getBookingById(id);
                setBooking(data);
            } catch (error) {
                console.error(error);
                router.push("/dashboard/student");
            } finally {
                setLoading(false);
            }
        };
        fetchBooking();
    }, [id, router]);

    const handlePay = async () => {
        if (!booking) return;
        setIsPaying(true);

        try {
            // For Cash/Simulation
            if (method === "cash") {
                await new Promise(r => setTimeout(r, 1500));
                alert("Please pay at the property to confirm your booking.");
                setIsPaid(true);
                return;
            }

            // 1. Create Order
            const order = await createRazorpayOrder(booking.id);

            // 2. Open Razorpay Modal (or simulate if script not loaded)
            if (!(window as any).Razorpay) {
                console.warn("Razorpay SDK not loaded. Simulating success...");
                await new Promise(r => setTimeout(r, 1500));

                // Simulated verification
                await verifyPayment({
                    razorpay_order_id: order.id,
                    razorpay_payment_id: "pay_simulated_" + Math.random().toString(36).slice(2),
                    razorpay_signature: "simulated_sig"
                });

                setIsPaid(true);
                return;
            }

            const options = {
                key: order.key,
                amount: order.amount,
                currency: order.currency,
                name: "RentPe",
                description: `Payment for ${booking.propertyName}`,
                order_id: order.id,
                handler: async function (response: any) {
                    try {
                        await verifyPayment(response);
                        setIsPaid(true);
                    } catch (err) {
                        alert("Verification failed. Please contact support.");
                    }
                },
                prefill: {
                    name: booking.guestName,
                    email: "user@example.com",
                },
                theme: { color: "#16a34a" },
            };

            const rzp = new (window as any).Razorpay(options);
            rzp.open();
        } catch (error: any) {
            console.error(error);
            alert(error.message || "Payment failed to initialize");
        } finally {
            setIsPaying(false);
        }
    };

    if (loading) return <div className="min-h-screen flex items-center justify-center">Loading payment details...</div>;
    if (!booking) return null;

    if (isPaid) {
        return (
            <div className="min-h-screen bg-muted/30 flex items-center justify-center p-4">
                <Card className="w-full max-w-lg shadow-xl">
                    <CardContent className="p-8 text-center space-y-4">
                        <div className="flex justify-center">
                            <div className="p-4 bg-green-100 rounded-full animate-bounce">
                                <CheckCircle className="h-12 w-12 text-green-600" />
                            </div>
                        </div>
                        <h2 className="text-2xl font-bold text-green-700">Payment Successful! ≡ƒÄë</h2>
                        <p className="text-muted-foreground">
                            Your payment for <strong>{booking.propertyName}</strong> has been received.
                        </p>
                        <p className="text-sm text-muted-foreground">
                            Booking ID: <strong>{booking.displayId}</strong>
                        </p>
                        <div className="bg-green-50 border border-green-200 p-3 rounded text-sm text-green-800">
                            Γ£à Your booking is now <strong>PAID & Confirmed</strong>. Welcome home!
                        </div>
                        <Button className="w-full mt-4" onClick={() => router.push("/dashboard/student")}>
                            Go to My Dashboard
                        </Button>
                    </CardContent>
                </Card>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-muted/30 flex items-center justify-center p-4">
            <Script src="https://checkout.razorpay.com/v1/checkout.js" />
            <Card className="w-full max-w-lg shadow-xl">
                <CardHeader className="space-y-1">
                    <div className="flex items-center justify-center mb-4">
                        <div className="p-3 bg-green-100 rounded-full">
                            <Lock className="h-8 w-8 text-green-600" />
                        </div>
                    </div>
                    <CardTitle className="text-2xl font-bold text-center">Complete Payment</CardTitle>
                    <CardDescription className="text-center">
                        PG: {booking.propertyName} ΓÇó {booking.occupancy}
                    </CardDescription>
                    <p className="text-center text-sm text-muted-foreground">Booking ID: <strong>{booking.displayId}</strong></p>
                </CardHeader>
                <CardContent className="space-y-6">
                    <div className="p-4 bg-muted rounded-md flex justify-between items-center">
                        <span className="font-medium">Total Amount</span>
                        <span className="text-xl font-bold">{booking.amount}</span>
                    </div>

                    {/* Payment Method Tabs */}
                    <div className="grid grid-cols-4 gap-2">
                        {[
                            { id: "upi", icon: Smartphone, label: "Online" },
                            { id: "card", icon: CreditCard, label: "Card" },
                            { id: "netbanking", icon: Building, label: "NetBank" },
                            { id: "cash", icon: Banknote, label: "Cash" },
                        ].map((m) => (
                            <button
                                key={m.id}
                                onClick={() => setMethod(m.id)}
                                className={cn(
                                    "flex flex-col items-center justify-center p-2 rounded-lg border transition-all text-xs font-medium gap-1",
                                    method === m.id || (method !== "cash" && m.id === "upi")
                                        ? "border-primary bg-primary/5 text-primary"
                                        : "border-muted hover:bg-muted/50 text-muted-foreground"
                                )}
                            >
                                <m.icon className="h-5 w-5" />
                                {m.label}
                            </button>
                        ))}
                    </div>

                    <div className="border rounded-lg p-4 bg-background">
                        {method !== "cash" ? (
                            <div className="space-y-2 text-center">
                                <p className="text-sm font-medium">Safe & Secure Online Payment</p>
                                <p className="text-xs text-muted-foreground">Powered by Razorpay. Includes UPI, Cards, and Netbanking.</p>
                            </div>
                        ) : (
                            <div className="space-y-2 text-center">
                                <p className="text-sm font-medium text-yellow-800">Pay at Property</p>
                                <p className="text-xs text-muted-foreground">Reserved but not confirmed until payment is made to the owner.</p>
                            </div>
                        )}
                    </div>

                </CardContent>
                <CardFooter className="flex flex-col space-y-4">
                    <Button
                        className="w-full text-lg h-12 bg-green-600 hover:bg-green-700"
                        onClick={handlePay}
                        disabled={isPaying}
                    >
                        {isPaying ? "Processing..." : method === "cash" ? "Confirm Pay at Property" : `Pay ${booking.amount}`}
                    </Button>
                    <p className="text-xs text-center text-muted-foreground">
                        Transaction encrypted with 256-bit SSL security.
                    </p>
                </CardFooter>
            </Card>
        </div>
    );
}

export default function PaymentPage() {
    return (
        <Suspense fallback={<div className="min-h-screen flex items-center justify-center">Loading...</div>}>
            <PaymentPortal />
        </Suspense>
    );
}

